// Acceptance of the lifetime-scoped AF-ON editor. Two fresh candidate sessions
// and one stock control. Exact assertions after every key. EMULATOR-ONLY.
// The failed route-f2 title check is not re-used as a pass: that frame was read
// before the zone title had been drawn. This runner settles to the literal hash.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/accept_f3.mjs om-emu
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/accept_f3.mjs om-emu\n');
  process.exit(2);
}
process.env.OM_EMU_MODEL = 'E147';
const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
const OUT = resolve('work/out/accept-f3.jsonl');
const CSV = resolve('work/out/overlay-changed-bytes.csv');
const BASE = 0x60021020;
const GETTER = 0x60063380;
const SETTER = 0x60063431;
const MODE = 0xa031eef7;
const MODE_CACHED = 0x6031eef7;
const PROFILE = 0xa031e920;
const PROFILE_CACHED = 0x6031e920;
const EXT = 0xa031eeb0;
const LAYOUT = {
  0x99a1: { off: 0x00, n: 8, width: 1 },
  0x9a41: { off: 0x08, n: 2, width: 1 },
  0x5962: { off: 0x0a, n: 6, width: 2 },
  0x1dd1: { off: 0x16, n: 10, width: 1 },
  0x84d1: { off: 0x20, n: 1, width: 1 },
  0x88b2: { off: 0x22, n: 1, width: 2 },
  0x90d1: { off: 0x24, n: 8, width: 1 },
  0x5a11: { off: 0x2c, n: 11, width: 1 },
  0x1de1: { off: 0x37, n: 8, width: 1 },
  0x1df1: { off: 0x3f, n: 8, width: 1 },
};
const TITLE = {
  all: '012041e4f3a3879914a8681e55a7ee206f7fe4c1e998177ba0a6f72520bb9d16',
  single: '42a83c79ead5126577e529b063c94c43e6d6d7a3177476b1be78a8c12c09b1a7',
  c1: 'b1b61046dadf4ac4716b1a9fc70a79d4b2a75e46c1373f6eb46707a54a314794',
};
const TRACK = ['k99a1', 'k9a41', 'k5962', 'k1dd1', 'k84d1', 'k88b2', 'k90d1', 'k1de1', 'k1df1', 'k99d2', 'kdfa1', 'k9fa1', 'k90a1'];
const HALF_KEYS = [...TRACK, 'k5a11'];
const KEY_META = {
  k99a1: [0x99a1, 8], k9a41: [0x9a41, 2], k5962: [0x5962, 6], k1dd1: [0x1dd1, 10],
  k1de1: [0x1de1, 8], k1df1: [0x1df1, 8], k84d1: [0x84d1, 1], k88b2: [0x88b2, 1],
  k90d1: [0x90d1, 8], k5a11: [0x5a11, 11], k99d2: [0x99d2, 3], kdfa1: [0xdfa1, 1],
  k9fa1: [0x9fa1, 3], k90a1: [0x90a1, 2],
};

const { loadNand, loadImage, loadBlock, patchedFirmware, createHash: fwHash } = await use('checks/lib/env.mjs');
const { IMAGE_BASE } = await use('src/fw/model.mjs');
const { Player } = await use('src/lab/player.mjs');
const { apply_uiin_layout } = await use('src/lab/play.mjs');
const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');
const { MenuWalk } = await use('src/lab/menuwalk.mjs');
const { write_png } = await use('checks/lib/png.mjs');
const { words_to_rgb } = await use('src/lab/display.mjs');
const { fileNvram } = await use('host/nvram.mjs');

const image = readFileSync(resolve('inputs/00_0100_50000020.decoded.bin'));
const patchOffsets = new Set();
const patches = [];
for (const row of readFileSync(CSV, 'utf8').trim().split(/\r?\n/).slice(1)) {
  const [o, , old, next] = row.split(',');
  const off = parseInt(o, 16);
  patchOffsets.add(off);
  if (image[off] !== parseInt(old, 16)) throw new Error('overlay stock mismatch at ' + (BASE + off).toString(16));
  const oldB = parseInt(old, 16);
  const neu = parseInt(next, 16);
  const last = patches.at(-1);
  if (last && off === last.offset + last.old.length) { last.old.push(oldB); last.neu.push(neu); }
  else patches.push({ offset: off, old: [oldB], neu: [neu] });
}
for (let addr = 0x6031eee7; addr <= 0x6031eef7; addr++) {
  const off = addr - BASE;
  if (image[off] !== 0xff || patchOffsets.has(off)) throw new Error('extension byte not free at ' + addr.toString(16));
}
const z5fw = patchedFirmware(patches.map((x, n) => ({
  block: 'main', offset: x.offset, old: Uint8Array.from(x.old), new: Uint8Array.from(x.neu), source: CSV, n,
})));
apply_uiin_layout(z5fw.rom);
const stockFw = { rom: loadImage(), resBlock: loadBlock(), summary: null, changed: [] };
apply_uiin_layout(stockFw.rom);

const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({ session: row.session, id: row.id, pass: row.pass, problems: row.problems, screen: row.screen, flag: row.flag }));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const native = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;
const pick = (cells, keys = TRACK) => {
  const out = {};
  for (const key of keys) out[key] = cells[key];
  return out;
};

const IMPORT_RE = /(?:from\s+|import\s*\(\s*|import\s+)['"]([^'"]+)['"]/g;
function resolveSpec(fromFile, spec) {
  if (!spec.startsWith('.')) return null;
  const base = resolve(dirname(fromFile), spec);
  for (const candidate of [base, base + '.mjs', base + '.js', join(base, 'index.mjs'), join(base, 'index.js')]) {
    if (existsSync(candidate) && statSync(candidate).isFile()) return candidate;
  }
  return null;
}
function inventory(file) {
  const seen = new Map();
  const queue = [file];
  while (queue.length) {
    const cur = queue.pop();
    if (!cur || seen.has(cur) || !existsSync(cur)) continue;
    const data = readFileSync(cur);
    seen.set(cur, { sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length });
    IMPORT_RE.lastIndex = 0;
    let match;
    const text = data.toString('utf8');
    while ((match = IMPORT_RE.exec(text))) {
      const next = resolveSpec(cur, match[1]);
      if (next) queue.push(next);
    }
  }
  return [...seen.entries()].map(([path, meta]) => ({ path: path.replaceAll('\\', '/'), ...meta }));
}

function boot(overlay, nvramPath) {
  const fw = overlay ? z5fw : stockFw;
  const pl = new Player(
    { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
    {
      ...fw, nand: loadNand(), createHash: fwHash, wallClock: () => performance.now() / 1000,
      machine: { coverage: { mark() {}, stub() {} } }, nvram: fileNvram(resolve(nvramPath)),
      patch: overlay ? fw.summary : null, patchRanges: overlay ? fw.changed : [], loaded: 'on',
    },
  );
  pl.camapp_components = true;
  pl.camapp_native_tra = true;
  return pl;
}

const controlGot = new Map();

function judge(step, got, halfAtEnter, profAtEnter) {
  const exp = step.expect || {};
  const problems = [];
  if (exp.screen && got.screen !== exp.screen) problems.push('screen');
  if (exp.flag !== undefined && got.flag !== exp.flag) problems.push('flag');
  if (exp.title && got.title !== exp.title) problems.push('title');
  if (exp.zone !== undefined && got.prof.k99a1[1] !== exp.zone) problems.push('zone');
  if (exp.pos !== undefined && got.prof.k5962[1] !== exp.pos) problems.push('pos');
  if (exp.size && (!same(got.prof.k1dd1.slice(0, 2), exp.size))) problems.push('size');
  if (exp.custom && (!same(got.prof.k1dd1.slice(2, 4), exp.custom))) problems.push('custom');
  if (exp.df4 !== undefined && got.prof.k1df1[4] !== exp.df4) problems.push('df4');
  if (exp.halfFrozen && halfAtEnter && !same(pick(got.half, HALF_KEYS), pick(halfAtEnter, HALF_KEYS))) problems.push('half-moved');
  if (exp.profHold && profAtEnter && !same(pick(got.prof), pick(profAtEnter))) problems.push('prof-moved');
  if (step.controlStep) {
    const control = controlGot.get(step.controlStep);
    if (!control) problems.push('control-unresolved');
    else if (step.controlOn === 'half') {
      if (!same(pick(got.half, HALF_KEYS), pick(control.half, HALF_KEYS)) || got.screen !== control.screen) problems.push('control');
    } else if (!same(pick(got.prof), pick(control.half))) problems.push('control-prof');
  }
  return problems;
}

async function session(name, spec) {
  const pl = boot(spec.overlay, spec.nvram);
  let shotN = 0;
  try {
    pl.open_session();
    const s = pl.session;
    const l = s.lab;
    const readByte = (addr) => l.sim.read(addr, 1)[0];
    const writeByte = (addr, value) => { const b = Buffer.alloc(1); b[0] = value & 0xff; l.sim.write(addr, b); };
    const writeU16 = (addr, value) => { const b = Buffer.alloc(2); b.writeUInt16LE(value & 0xffff, 0); l.sim.write(addr, b); };
    const halfWord = (addr) => { const b = l.sim.read(addr, 2); return b[0] | (b[1] << 8); };
    const slotAddr = (key, index) => {
      const row = LAYOUT[key];
      if (!row || index < 0 || index >= row.n) return null;
      return EXT + row.off + index * row.width;
    };
    if (spec.hooks) {
      l.hook(native(GETTER), (h, r) => {
        const addr = readByte(MODE) === 1 ? slotAddr(r.d0 & 0xffff, r.d1 & 0xffff) : null;
        if (addr === null) { l.passthrough(r); return; }
        h.finish(r, { d0: LAYOUT[r.d0 & 0xffff].width === 2 ? halfWord(addr) : readByte(addr) });
      }, 'EMULATOR-ONLY combined: AF-ON getter, flag 0xa031eef7');
      l.hook(native(SETTER), (h, r) => {
        const key = r.d0 & 0xffff;
        const index = r.d1 & 0xffff;
        const addr = readByte(MODE) === 1 ? slotAddr(key, index) : null;
        if (addr === null) { l.passthrough(r); return; }
        if (LAYOUT[key].width === 2) writeU16(addr, r.a1 >>> 0);
        else writeByte(addr, r.a1 >>> 0);
        if (key === 0x99a1 && (index === 0 || index === 1)) {
          writeByte(PROFILE, r.a1 & 0xff);
          writeByte(PROFILE_CACHED, r.a1 & 0xff);
        }
        h.finish(r, { d0: 0 });
      }, 'EMULATOR-ONLY combined: AF-ON setter, flag 0xa031eef7');
    }
    const callSaved = (fn) => {
      const saved = l.sim.registers();
      try { return fn(); }
      finally { l.sim.reset(saved); }
    };
    const readKey = (key, index) => callSaved(() => l.call(native(GETTER), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff);
    const writeKey = (key, index, value) => callSaved(() => l.call(native(SETTER), { d0: key, d1: index, a1: value }, null, null, 200000));
    const arr = (key, n) => Array.from({ length: n }, (_, i) => readKey(key, i));
    const setMode = (value) => { writeByte(MODE, value); writeByte(MODE_CACHED, value); };
    const cells = () => ({
      profileByte: readByte(PROFILE),
      k99a1: arr(0x99a1, 8), k9a41: arr(0x9a41, 2), k5962: arr(0x5962, 6),
      k1dd1: arr(0x1dd1, 10), k1de1: arr(0x1de1, 8), k1df1: arr(0x1df1, 8),
      k84d1: readKey(0x84d1, 0), k88b2: readKey(0x88b2, 0), k90d1: arr(0x90d1, 8),
      k5a11: arr(0x5a11, 11), k99d2: arr(0x99d2, 3), kdfa1: readKey(0xdfa1, 0),
      k9fa1: arr(0x9fa1, 3), k90a1: [readKey(0x90a1, 0), readKey(0x90a1, 1)],
    });
    const idle = (ms) => { const to = l.lab_time() + ms * 1e6; while (l.lab_time() < to) s.idle_slice(Math.min(to, l.lab_time() + 50e6)); };
    const key = (k, d) => { s.key(k, d); s.camapp.pump(); };
    const press = (k) => { key(k, 'down'); idle(80); key(k, 'up'); idle(700); };
    const dial = (which, n) => { s.dial_input(which, n); s.camapp.pump(); idle(700); };
    const walk = new MenuWalk({ press, frame: () => s.frame('boundary'), draws: () => l.draw_log }, { limit: 8 });
    const titleHash = (frame) => {
      const [w, h, words] = frame;
      const y1 = Math.max(1, Math.min(h, Math.floor(h * 0.16)));
      const x0 = Math.floor(w * 0.22);
      const x1 = Math.floor(w * 0.78);
      const buf = Buffer.alloc((x1 - x0) * y1 * 4);
      let o = 0;
      for (let y = 0; y < y1; y++) for (let x = x0; x < x1; x++) { buf.writeUInt32LE(words[y * w + x] >>> 0, o); o += 4; }
      return createHash('sha256').update(buf).digest('hex');
    };
    const grab = (title) => {
      let frame = null;
      try { frame = walk.read().frame; } catch { frame = s.frame('boundary'); }
      if (!frame) throw new Error('screenshot failed');
      if (title) {
        for (let i = 0; i < 6 && titleHash(frame) !== title; i++) {
          idle(400);
          try { frame = s.frame('boundary'); } catch { /* keep the previous frame */ }
        }
      }
      return frame;
    };
    let halfAtEnter = null;
    let profAtEnter = null;
    const saves = () => (l.store_log?.nvram?.saves ?? []).map((x) => ({ store: x.store, from: x.from, posted: !!x.posted }));
    const initProfile = () => {
      const bytes = [2, 0, 2, 0, 2, 0, 5, 5];
      for (let i = 0; i < 8; i++) writeByte(EXT + i, bytes[i]);
      writeByte(PROFILE, 0);
      writeByte(PROFILE_CACHED, 0);
      writeByte(EXT + 8, 0);
      writeByte(EXT + 9, 1);
      for (let i = 0; i < 6; i++) writeU16(EXT + 0x0a + i * 2, 526);
      const custom = [27, 39, 3, 3, 3, 3, 3, 3, 3, 3];
      for (let i = 0; i < 10; i++) writeByte(EXT + 0x16 + i, custom[i]);
      writeByte(EXT + 0x20, 2);
      writeU16(EXT + 0x22, 526);
      const area = [2, 2, 2, 2, 2, 2, 5, 5];
      for (let i = 0; i < 8; i++) writeByte(EXT + 0x24 + i, area[i]);
      for (let i = 0; i < 11; i++) writeByte(EXT + 0x2c + i, 1);
      for (let i = 0; i < 8; i++) writeByte(EXT + 0x37 + i, 1);
      const df = [1, 1, 1, 1, 0, 0, 0, 0];
      for (let i = 0; i < 8; i++) writeByte(EXT + 0x3f + i, df[i]);
      setMode(0);
    };
    let remembered = null;
    const snap = (step) => {
      const frame = grab(step.expect && step.expect.title);
      if (!frame) throw new Error('screenshot failed at ' + name + ' ' + step.id);
      const file = resolve('work/out/accept-f3-' + name + '-' + String(shotN).padStart(2, '0') + '-' + step.id + '.png');
      shotN += 1;
      write_png(file, frame[0], frame[1], words_to_rgb(frame[2]));
      const saved = spec.hooks ? readByte(MODE) : 0;
      if (spec.hooks) setMode(0);
      const half = cells();
      let prof = null;
      if (spec.hooks) { setMode(1); prof = cells(); setMode(saved); }
      else prof = half;
      return {
        screen: s.screen(), flag: spec.hooks ? saved : 0, half, prof,
        title: titleHash(frame), screenshot: file.split(/[/\\]/).pop(),
      };
    };
    const act = (step) => {
      if (step.action === 'enter') setMode(1);
      else if (step.action === 'up') press('up');
      else if (step.action === 'right') press('right');
      else if (step.action === 'ok') press('ok');
      else if (step.action === 'menu') press('menu');
      else if (step.action === 'dial') dial('main', 1);
      else if (step.action === 'sub') dial('sub', 1);
      else if (step.action === 's1') press('s1');
      else if (step.action === 'down') press('down');
      else if (step.action === 'left') press('left');
      else if (step.action === 'shoot') { for (let i = 0; i < 8 && s.screen() !== 'shooting'; i++) press('menu'); }
      else if (step.action === 'init') initProfile();
      else if (step.action === 'remember') remembered = cells();
      else if (step.action === 'restore') {
        const now = cells();
        for (const [name, [key, n]] of Object.entries(KEY_META)) {
          const before = remembered[name];
          const after = now[name];
          if (Array.isArray(before)) {
            for (let i = 0; i < n; i++) if (before[i] !== after[i]) writeKey(key, i, before[i]);
          } else if (before !== after) writeKey(key, 0, before);
        }
      }
      else if (step.action === 'size-open') {
        press('menu');
        for (let i = 0; i < 24; i++) {
          let texts = [];
          try { texts = walk.read().texts.map((t) => t.text); } catch { texts = []; }
          if (texts.some((t) => String(t).includes('AF Target Settings'))) break;
          press('left');
        }
        press('ok');
        for (let i = 0; i < 5; i++) press('down');
        if (spec.hooks) setMode(1);
        press('right');
      }
      if (step.disarm) setMode(0);
    };
    if (spec.hooks) initProfile();
    idle(1000);
    const bootSaves = saves();
    for (const step of spec.steps) {
      act(step);
      const got = snap(step);
      const problems = judge(step, got, halfAtEnter, profAtEnter);
      if (step.baseline) { halfAtEnter = got.half; profAtEnter = got.prof; }
      emit({
        session: name, id: step.id, action: step.action, controlStep: step.controlStep || null,
        pass: problems.length === 0, problems, fatalShots: true,
        screen: got.screen, flag: got.flag, title: got.title, screenshot: got.screenshot,
        half: pick(got.half, HALF_KEYS), prof: pick(got.prof), profileByte: got.prof.profileByte,
        zone: got.prof.k99a1[1],
      });
      if (spec.record) controlGot.set(step.id, got);
      if (problems.length) throw new Error('assertion failed at ' + name + ' ' + step.id + ' ' + problems.join(','));
    }
    const before = saves();
    const beforeHash = existsSync(resolve(spec.nvram)) ? createHash('sha256').update(readFileSync(resolve(spec.nvram))).digest('hex') : '';
    for (let i = 0; i < 4 && s.screen() !== 'shooting'; i++) press('menu');
    press('menu');
    idle(800);
    press('menu');
    idle(800);
    const afterMenu = saves();
    let powerError = null;
    let power = null;
    try { power = s.power_down(); }
    catch (e) { powerError = String(e && e.message || e); }
    const afterPower = saves();
    const afterHash = existsSync(resolve(spec.nvram)) ? createHash('sha256').update(readFileSync(resolve(spec.nvram))).digest('hex') : '';
    const grew = afterPower.length > before.length || afterMenu.length > before.length || (afterHash !== '' && afterHash !== beforeHash);
    emit({
      session: name, id: 'save', action: 'save', pass: grew, problems: grew ? [] : ['save'],
      fatalShots: true, screen: 'save', flag: spec.hooks ? readByte(MODE) : 0,
      savesBefore: before, savesAfterMenu: afterMenu, savesAfterPower: afterPower,
      storeChanged: afterHash !== beforeHash, powerNull: power === null, powerError, bootSaves: bootSaves.length,
    });
    if (!grew) throw new Error('save did not complete at ' + name);
    return true;
  } finally {
    if (pl.session) pl.close_session();
  }
}

const parity = [
  { id: 'p-up', action: 'up', expect: { screen: 'direct', title: TITLE.all, zone: 0 }, controlOn: 'prof' },
  { id: 'p-dial', action: 'dial', expect: { screen: 'direct', title: TITLE.single, zone: 1, size: [1, 1] }, controlOn: 'prof' },
  { id: 'p-right', action: 'right', expect: { screen: 'direct', title: TITLE.single, zone: 1, pos: 529 }, controlOn: 'prof' },
  { id: 'p-menu', action: 'menu', disarm: true, expect: { flag: 0, zone: 1, pos: 529 }, controlOn: 'prof' },
  { id: 'p-shoot', action: 'shoot', expect: { screen: 'shooting', flag: 0, zone: 1 }, controlOn: 'prof' },
];
const unit = (id, controlId) => [
  { id: id + '-up', action: 'up', controlStep: controlId ? controlId + '-up' : null, controlOn: 'half', expect: { screen: 'direct' } },
  { id: id + '-dial', action: 'dial', controlStep: controlId ? controlId + '-dial' : null, controlOn: 'half', expect: { screen: 'direct' } },
  { id: id + '-ok', action: 'ok', controlStep: controlId ? controlId + '-ok' : null, controlOn: 'half', expect: { screen: 'shooting' } },
];
const c1dial = [1, 2, 3, 5, 10, 6].map((zone, i) => ({
  id: 'c1-dial-' + i, action: 'dial',
  expect: { screen: 'direct', flag: 1, zone, title: zone === 1 ? TITLE.single : zone === 6 ? TITLE.c1 : undefined, halfFrozen: true },
}));
const sizeSteps = (hooked) => [
  { id: 'size-remember', action: 'remember', expect: {} },
  { id: 'size-open', action: 'size-open', baseline: true, expect: hooked ? { flag: 1, halfFrozen: true } : {} },
  { id: 'size-v', action: 'dial', expect: hooked ? { flag: 1, halfFrozen: true } : {} },
  { id: 'size-h', action: 'sub', expect: hooked ? { flag: 1, halfFrozen: true } : {} },
  { id: 'size-ok', action: 'ok', disarm: hooked, expect: hooked ? { flag: 0, custom: [5, 1], df4: 1, halfFrozen: true } : { custom: [5, 1], df4: 1 } },
];

function candidateSteps() {
  const hold = (steps) => steps.map((step) => ({ ...step, expect: { ...step.expect, flag: 0, profHold: true } }));
  return [
    { id: 'base', action: 'none', expect: { screen: 'shooting', flag: 0 } },
    { id: 'enter', action: 'enter', baseline: true, expect: { screen: 'shooting', flag: 1 } },
    ...parity.map((step) => ({ ...step, expect: { ...step.expect, flag: step.expect.flag ?? 1, halfFrozen: true }, controlStep: step.id })),
    { id: 'h1-mark', action: 'none', baseline: true, expect: { flag: 0, zone: 1 } },
    ...[
      { id: 'h1-up', action: 'up', controlStep: 'p-up', controlOn: 'half', expect: { screen: 'direct', flag: 0, profHold: true } },
      { id: 'h1-dial', action: 'dial', controlStep: 'p-dial', controlOn: 'half', expect: { screen: 'direct', flag: 0, title: TITLE.single, profHold: true } },
      { id: 'h1-right', action: 'right', controlStep: 'p-right', controlOn: 'half', expect: { screen: 'direct', flag: 0, profHold: true } },
      { id: 'h1-menu', action: 'menu', controlStep: 'p-menu', controlOn: 'half', expect: { flag: 0, profHold: true } },
      { id: 'h1-shoot', action: 'shoot', controlStep: 'p-shoot', controlOn: 'half', expect: { screen: 'shooting', flag: 0, profHold: true } },
    ],
    { id: 'c1-init', action: 'init', expect: { flag: 0 } },
    { id: 'c1-enter', action: 'enter', baseline: true, expect: { flag: 1 } },
    { id: 'c1-up', action: 'up', expect: { screen: 'direct', flag: 1, title: TITLE.all, zone: 0, halfFrozen: true } },
    ...c1dial,
    { id: 'c1-ok', action: 'ok', disarm: true, baseline: true, expect: { screen: 'shooting', flag: 0, zone: 6, size: [3, 3], custom: [3, 3], halfFrozen: true } },
    ...hold(unit('h2', 'n1')).map((step, i, all) => (i === all.length - 1 ? { ...step, baseline: true } : step)),
    ...sizeSteps(true),
    { id: 'size-shoot', action: 'shoot', baseline: true, expect: { screen: 'shooting', flag: 0 } },
    ...hold(unit('h3', 'n2')),
    { id: 's1-enter', action: 'enter', baseline: true, expect: { flag: 1 } },
    { id: 's1-up', action: 'up', expect: { screen: 'direct', flag: 1, halfFrozen: true } },
    { id: 's1-exit', action: 's1', disarm: true, expect: { flag: 0, halfFrozen: true } },
    { id: 's1-shoot', action: 'shoot', baseline: true, expect: { screen: 'shooting', flag: 0 } },
    ...hold(unit('h4', 'n3')),
  ];
}
function controlSteps() {
  const plain = (steps) => steps.map((step) => ({ ...step, controlStep: null, controlOn: null, expect: { screen: step.expect.screen, title: step.expect.title, zone: step.expect.zone, pos: step.expect.pos, size: step.expect.size } }));
  return [
    ...plain(parity.map((step) => ({ ...step, disarm: false }))),
    ...plain(unit('n1', null)),
    ...sizeSteps(false),
    { id: 'size-restore', action: 'restore', expect: {} },
    { id: 'size-shoot', action: 'shoot', expect: { screen: 'shooting' } },
    ...plain(unit('n2', null)),
    { id: 's1-remember', action: 'remember', expect: {} },
    { id: 's1-press', action: 's1', expect: {} },
    { id: 's1-restore', action: 'restore', expect: {} },
    { id: 's1-shoot', action: 'shoot', expect: { screen: 'shooting' } },
    ...plain(unit('n3', null)),
  ];
}

function banks(file) {
  const doc = JSON.parse(readFileSync(resolve(file), 'utf8'));
  return { M: Buffer.from(doc.M, 'base64'), E: Buffer.from(doc.E, 'base64') };
}

let failed = null;
try {
  const modules = inventory(resolve('work/scripts/accept_f3.mjs'));
  writeFileSync(resolve('work/out/import-inventory-f3.json'), JSON.stringify({
    note: 'SHA-256 of the runner before the sessions. Emulator imports are resolved from this file.',
    hashed: 'execution', modules,
  }, null, 2) + '\n');
  emit({ session: 'meta', id: 'imports', pass: true, problems: [], modules: modules.length, fatalShots: true });
  await session('control', {
    overlay: false, hooks: false, record: true,
    nvram: 'work/out/nvram-accept-f3-control.json',
    steps: controlSteps(),
  });
  for (const name of ['c1', 'c2']) {
    await session(name, {
      overlay: true, hooks: true, record: false,
      nvram: 'work/out/nvram-accept-f3-' + name + '.json',
      steps: candidateSteps(),
    });
  }
  const control = banks('work/out/nvram-accept-f3-control.json');
  const first = (a, b) => { const n = Math.min(a.length, b.length); for (let i = 0; i < n; i++) if (a[i] !== b[i]) return i; return a.length === b.length ? -1 : n; };
  for (const name of ['c1', 'c2']) {
    const store = banks('work/out/nvram-accept-f3-' + name + '.json');
    const sameM = control.M.equals(store.M);
    const sameE = control.E.equals(store.E);
    emit({
      session: name, id: 'store', pass: sameM && sameE, problems: sameM && sameE ? [] : ['store'],
      fatalShots: true, mBytes: store.M.length, eBytes: store.E.length,
      mDiff: first(control.M, store.M), eDiff: first(control.E, store.E),
    });
    if (!sameM || !sameE) throw new Error('store mismatch ' + name);
  }
  const pl = boot(true, 'work/out/nvram-accept-f3-c1.json');
  pl.open_session();
  const l = pl.session.lab;
  const to = l.lab_time() + 800 * 1e6;
  while (l.lab_time() < to) pl.session.idle_slice(Math.min(to, l.lab_time() + 50e6));
  const mirror = Array.from(l.sim.read(EXT, 71));
  const flag = l.sim.read(MODE, 1)[0];
  const zone = l.sim.read(PROFILE, 1)[0];
  const mirrorFF = mirror.every((b) => b === 0xff);
  emit({
    session: 'reopen', id: 'reopen', pass: flag === 0xff && zone === 0 && mirrorFF,
    problems: flag === 0xff && zone === 0 && mirrorFF ? [] : ['reopen'],
    fatalShots: true, flag, zone, mirror,
    note: '0xFF is the image byte: uninitialised, the editor is not in AF-ON mode and the mirror is not a stored profile. Zone byte 0 is the Z5 image default.',
  });
  pl.close_session();
  if (!(flag === 0xff && zone === 0 && mirrorFF)) throw new Error('reopen profile was not the image default');
  emit({ session: 'meta', id: 'done', pass: true, ok: true, problems: [], fatalShots: true });
} catch (e) {
  failed = String(e && e.stack ? e.stack : e);
  emit({ session: 'meta', id: 'done', pass: false, ok: false, problems: ['run'], error: failed, fatalShots: true });
  process.exitCode = 1;
} finally {
  writeFileSync(OUT, lines.join('\n') + (lines.length ? '\n' : ''));
}
if (failed) process.exit(1);
